// ── Parse DeepSeek response → Discord Embeds (robuste) ──
const raw = $input.first().json;

// 0) Erreur API
if (raw?.error) {
  const msg = raw.error.message || raw.error.code || JSON.stringify(raw.error);
  return [{ json: { embeds: [{
    title: '❌ DeepSeek — Erreur API',
    description: String(msg).slice(0, 1800),
    color: 15158332
  }] } }];
}

// 1) Structure attendue
if (!raw?.choices || !raw.choices[0]?.message) {
  const excerpt = JSON.stringify(raw, null, 2).slice(0, 1800);
  return [{ json: { embeds: [{
    title: '⚠️ DeepSeek — Réponse inattendue',
    description: 'Structure inattendue (pas de choices[0].message). Extrait :\n```\n' + excerpt + '\n```',
    color: 15105570
  }] } }];
}

const content = raw.choices[0].message.content;
if (!content) {
  const excerpt = JSON.stringify(raw, null, 2).slice(0, 1800);
  return [{ json: { embeds: [{
    title: '❌ DeepSeek — Contenu vide',
    description: 'choices[0].message.content est vide. Extrait :\n```\n' + excerpt + '\n```',
    color: 15158332
  }] } }];
}

// 2) Parse JSON
let data;
try {
  let cleaned = String(content).trim();
  if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '').trim();
  }
  data = JSON.parse(cleaned);
} catch (e) {
  const excerpt = String(content).slice(0, 1800);
  return [{ json: { embeds: [{
    title: '⚠️ DeepSeek — JSON invalide',
    description: `Erreur: ${e.message}\n\nExtrait:\n\`\`\`\n${excerpt}\n\`\`\``,
    color: 15105570
  }] } }];
}

function truncate(str, max) {
  if (!str) return '';
  str = String(str);
  return str.length > max ? str.slice(0, max - 1) + '…' : str;
}
function clamp(val, min, max) {
  const n = Number(val);
  if (isNaN(n)) return min;
  return Math.max(min, Math.min(max, Math.round(n)));
}

const embeds = [];
const dateStr = new Date().toLocaleDateString('fr-FR');

embeds.push({
  title: '🧠 ' + truncate(data.title || 'Veille stratégique', 200),
  description: '📅 **' + dateStr + '**',
  color: 5793266
});

const colorMap = { high: 15105570, medium: 3447003, low: 2067276 };
const emojiMap = { high: '🔥', medium: '⭐', low: 'ℹ️' };

const sections = Array.isArray(data.sections) ? data.sections : [];
for (const s of sections.slice(0, 6)) {
  const name = s.name || 'Section';
  const imp = ['high','medium','low'].includes(String(s.importance).toLowerCase()) ? String(s.importance).toLowerCase() : 'medium';
  const score = clamp(s.score, 0, 100);
  const bullets = Array.isArray(s.bullets) ? s.bullets.slice(0, 3) : [];
  const why = truncate(s.why_it_matters, 180);

  const bulletText = bullets.length ? bullets.map(b => '• ' + truncate(b, 120)).join('\n') : '• Aucune information';
  const whyText = why ? `\n\n💡 **Pourquoi :** ${why}` : '';

  embeds.push({
    title: `${name} ${emojiMap[imp]} ${imp.toUpperCase()} (${score}/100)`,
    description: bulletText + whyText,
    color: colorMap[imp] || colorMap.medium
  });
}

if (Array.isArray(data.top_actions)) {
  embeds.push({
    title: '🎯 Actions recommandées',
    description: data.top_actions.slice(0, 3).map(a => '→ ' + truncate(a, 140)).join('\n') || '→ N/A',
    color: 2067276
  });
}

return [{ json: { embeds: embeds.slice(0, 10) } }];
